// use getOrCreate or make any of the lset sanity checks that Append does.
func (a *headAppender) UpdateMetadata(ref storage.SeriesRef, lset labels.Labels, meta metadata.Metadata) (storage.SeriesRef, error) {
	s := a.lookupSeries(ref, lset)
	if s != nil {
		ref = storage.SeriesRef(s.ref)
	}
	if s == nil {
		return 0, a.unknownSeriesMetadataError(ref, lset)
	}

	if a.metadataChanged(s, meta) {
		a.recordMetadataUpdate(s, meta)
	}

	return ref, nil
}

